import type { Metadata } from "next";
import Breadcrumb from "@/components/header/breadcrumb";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faArrowRotateLeft,
  faCreditCard,
  faMoneyBill,
  faPercent,
} from "@fortawesome/free-solid-svg-icons";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title: "Terms of Use - TravelShop Booking",
  description:
    "Explore the TravelShop Booking Site Terms of Use for clear guidelines and policies. Please read and fully understand the TravelShop Booking Terms and Conditions.",
  alternates: {
    canonical: "https://travelshopbooking.com/terms-of-use",
  },
};

const prose =
  "tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c] [&_p]:tw-mt-0 [&_p]:tw-mb-4 [&_h2]:tw-text-[19px] [&_h2]:tw-font-bold [&_h2]:tw-text-[#14101c] [&_h2]:tw-mt-8 [&_h2]:tw-mb-3 [&_h3]:tw-text-[16px] [&_h3]:tw-font-bold [&_h3]:tw-text-[#14101c] [&_h3]:tw-mt-5 [&_h3]:tw-mb-2 [&_a]:tw-text-[#854ec9] [&_a]:tw-font-semibold [&_strong]:tw-text-[#14101c]";

const policyCards = [
  {
    icon: faArrowRotateLeft,
    text: 'Land tours "only" cancellation policy: Fully refundable in any cases and credit towards to the next event under Force Majeure conditions',
  },
  {
    icon: faPercent,
    text: "Tours with domestic flight cancellation policy: Booking day 50 % Non-refundable, 5 Weeks before 50% credit, 4 Weeks before Non-refundable",
  },
  {
    icon: faMoneyBill,
    text: 'Land tours "only" cancellation policy: Fully refundable in any cases and credit towards to the next event under Force Majeure conditions',
  },
];

const refundCards = [
  {
    title: "Cancellation and Refunds",
    body: "Cancellations must be made in writing and signed by the tour participants. In the event that a tour participant cancels his or her reservation, the cancellation penalty may apply. The reservation deposit of 15% will not be refunded in case of any cancellations that are outside the Force Majeure conditions.",
  },
  {
    title: "Guarantee Prices",
    body: "Our price guarantees that no increase in land costs will occur once you have paid the deposit for your tour. This is your protection against international currency fluctuations. When you have paid for your domestic flight in full, there will be no change in the cost of the ticket, even if airfares rise later.",
  },
  {
    title: "Last Minute Bookings",
    body: "The price of your domestic flights may change when booking at last minute. Prices indicated are subject to flight availability and a minimum of 4 weeks notification prior to the commencement of your tour. Your last minute land tours will be arranged according to the availability of services. Prices will not change, unless TravelShop Booking has to make any change or add any extra service for the last minute booking.",
  },
  {
    title: "Discounts / Special Offers",
    body: "On all discounted tours full payment required at the time of booking. When booking any of our tours in advance, please ask us about any available discounts. Please follow all available discounts by DEALS button on the Homepage.",
  },
];

const infoCards: {
  title: string;
  image: string;
  imageLeft: boolean;
  body: string[];
}[] = [
  {
    title: "Group Tours",
    image: "/images/terms/group-tours.jpg",
    imageLeft: true,
    body: [
      "Please ask for special group discounts if you are a group of more than 6 people. For the accommodation, we can manage single, double and triple rooms depending on the number of people and according to availability. Note that in some periods of the year, the group sizes will be from 10 to a maximum of 30. In such cases, you may be eligible for Private Tours which would be much convenient and affordable.",
    ],
  },
  {
    title: "Before Your Travel",
    image: "/images/terms/pre-travel.jpg",
    imageLeft: false,
    body: [
      "A copy of all your flight tickets, tour voucher, itinerary, hotel contact information and confirmation email will be sent to you upon request before your arrival in Turkey. We also give this to you in your welcome pack upon arrival at the airport. You should check all the information carefully (names, arrival and departure times, flight details...) and notify us immediately of any discrepancies, as once booked and confirmed we will not take responsibility for any errors in this information.",
    ],
  },
  {
    title: "Upon Arrival",
    image: "/images/terms/arrival.jpg",
    imageLeft: true,
    body: [
      'When you arrive after your customs and baggage collection, our friendly staff will be waiting with your name and a TravelShop Booking sign at the arrivals gate"s designated spot. They will assist you to our transportation and with your onward tour.',
      'Please keep in mind that a maximum of 15-20 kilos are allowed on domestic flights. For international flights, check with your provider before packing. Please also check with your local authorities for travelling abroad for COVID-19 procedures and act accordingly. For Turkish Governmental requirements, please check the "72 Hour Prior Notice" on the Homepage Menu.',
    ],
  },
  {
    title: "Travel Insurance",
    image: "/images/terms/insurance.png",
    imageLeft: false,
    body: [
      "Though we do not provide, we recommend that you purchase travel insurance for the same reason that you have house and car insurance - to protect you, your loved ones, your possessions and your travel investment. If you or your family have unexpected health problems, experience flight delays or have possessions stolen during your vacation, you will be covered for costs.",
    ],
  },
  {
    title: "Transportation",
    image: "/images/terms/transportation.webp",
    imageLeft: true,
    body: [
      "All the buses we use are luxury, air conditioned buses. Most of them have TV and freezer available and our luxury Mercedes Sprinters have internet and mini bar available. All of the buses used intercity are very clean, comfortable and safe. You will see a lot of interesting and beautiful views during the journey. For long bus journeys, we provide a small rest break every 2.5 hours. *We will allocate the bus according to the availability and the number of pax requested. *Please keep in mind our bus luggage restriction. We need to leave some free seats for Pandemic measurements.",
    ],
  },
  {
    title: "Passports & Visas",
    image: "/images/terms/passport-visa.jpg",
    imageLeft: false,
    body: [
      "You are responsible for ensuring that you have all the necessary travel documents and that they are valid and effective. You will need a current passport that is valid for at least 6 months and the necessary visa documentation. Passengers must apply for and obtain a multiple entry Turkey visa for our Turkey programmes, multiple entry Schengen visa for our Greek tour programmes and Single entry tourist visa for our Egypt programmes. If you take a tour in North Cyprus, you will need a double entry visa.",
    ],
  },
];

export default function TermsPage() {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Header band */}
      <section className="tw-bg-[#faf9fc] tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1100px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-10 md:tw-py-14">
          <Breadcrumb
            items={[{ pageTitle: "Terms of Use", pageUrl: "/terms-of-use" }]}
          />
          <h1 className="tw-mt-4 tw-text-[clamp(28px,4vw,44px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Terms of Use
          </h1>
        </div>
      </section>

      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1100px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          {/* Pricing + reservation */}
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 tw-gap-5 lg:tw-gap-6">
            <div
              className={`tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 md:tw-p-7 ${prose}`}
            >
              <h2 className="!tw-mt-0">1. Pricing Tour Options</h2>
              <p>
                TravelShop Booking offers many travel options, tours, packages
                and other services with three different hotel category options
                within each tour. These range from carefully selected 3, 4,
                &amp; 5 star hotels all around Turkey. Prices are set in
                November and are valid for a year coomonly. Prices will be
                maintained for bookings outside this period on receipt of the
                deposit. Our prices are fixed up until April 2022 due to Covid-
                19 outbreak.
              </p>
              <h3>1.1 Land Tours</h3>
              <p>
                Tours may be booked without hotel accommodation if you prefer to
                book your own hotel. We have given the name of &quot;Land
                Tour&quot; to this type of tour. Prices include all items
                mentioned under TOUR INCLUDES lists, but exclude hotel
                accommodation, breakfasts and dinners. You will not be refunded
                for any of the services included in the tour which you do not
                use.
              </p>
            </div>
            <div
              className={`tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 md:tw-p-7 ${prose}`}
            >
              <h2 className="!tw-mt-0">2. Reservation - Deposit – Payments</h2>
              <h3>2.1 Reservation</h3>
              <p>
                Having fully explored the TravelShop Booking website and found a
                tour which suits you, simply complete the short booking form
                located at the bottom of each tour itinerary page or call our
                office in Istanbul on +90 549 540 5402. We will check
                availability for your preferred date and respond by e-mail or
                telephone. Once availability has been confirmed and you are
                happy to go ahead with the booking, we charge a booking deposit
                to your credit card. An e-mail confirming all the details of the
                tour, including hotel name and domestic flights if booked with
                us, will be sent to you immediately. Most importantly, please
                ensure you send us your full name as per your passport so we can
                make your flight reservations correctly.
              </p>
              <h3>2.2 Deposit and Payments</h3>
              <p>
                Tour payments are divided into 3 steps. Your reservation will be
                confirmed upon receipt of your online order and a non-refundable
                deposit as shown in the table below. Progressive payment is then
                due as indicated below. All cancellations are subject to a
                written request and to be confirmed in return.
              </p>
            </div>
          </div>

          {/* Cancellation policy icon cards */}
          <div className="tw-mt-6 tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {policyCards.map((card, i) => (
              <div
                key={i}
                className="tw-rounded-2xl tw-bg-[#faf9fc] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 tw-text-center"
              >
                <div className="tw-mx-auto tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={card.icon} className="tw-text-2xl" />
                </div>
                <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.text}
                </p>
              </div>
            ))}
          </div>

          {/* Bank details */}
          <div className="tw-mt-12 tw-text-center">
            <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              TravelShop Booking bank details
            </h2>
            <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c] tw-max-w-[680px] tw-mx-auto">
              These payments can be made via credit card, bank transfer or
              travellers cheque. Please find below TravelShop Booking bank
              details for booking via bank transfer.
            </p>
          </div>
          <div className="tw-mt-6 tw-grid tw-grid-cols-1 md:tw-grid-cols-2 tw-gap-5 lg:tw-gap-6">
            <div className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 tw-text-[14px] tw-leading-[2] tw-text-[#5d556c]">
              <div>
                <strong className="tw-text-[#14101c]">Account Name: </strong>
                Bodrum Kalender Otelcilik ve Yatcilik, Turizm, Seyahat Limited
                Sirketi
              </div>
              <div>
                <strong className="tw-text-[#14101c]">Bank Name: </strong>ZIRAAT
                BANKASI
              </div>
              <div>
                <strong className="tw-text-[#14101c]">Bank Branch: </strong>
                Sirinevler-Istanbul Subesi
              </div>
              <div>
                <strong className="tw-text-[#14101c]">
                  Bank Branch Code:{" "}
                </strong>
                826
              </div>
            </div>
            <div className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 tw-text-[14px] tw-leading-[2] tw-text-[#5d556c]">
              <div>
                <strong className="tw-text-[#14101c]">€ - EURO IBAN: </strong>
                TR660001000826614727715007
              </div>
              <div>
                <strong className="tw-text-[#14101c]">$ - USD IBAN: </strong>
                TR230001000826614727715005
              </div>
              <div>
                <strong className="tw-text-[#14101c]">£ - GBP IBAN: </strong>
                TR390001000826614727715008
              </div>
              <div>
                <strong className="tw-text-[#14101c]">₺ - TL IBAN: </strong>
                TR500001000826614727715004
              </div>
              <div>
                <strong className="tw-text-[#14101c]">Swift Code(BIC): </strong>
                TCZBTR2A
              </div>
            </div>
          </div>

          {/* Payment info */}
          <div className={`tw-mt-10 ${prose}`}>
            <div className="tw-flex tw-justify-center tw-mb-6">
              <div className="tw-flex tw-h-16 tw-w-16 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                <FontAwesomeIcon icon={faCreditCard} className="tw-text-3xl" />
              </div>
            </div>
            <p>
              Visa and Mastercard payments can be charged in Dollars, Pounds,
              Euro or Turkish Lira. A 4% bank fee will be charged if payment is
              made via American Express. Other payment methods are free of fee
              charges. You may also contact us for other payment methods.
            </p>
            <p>
              The full amount of your tour must be paid 14 days before the tour
              start date. If full payment is not received by this time we
              consider it a cancellation and cancellation penalties will apply.
              If you have booked any of our tours including domestic flight
              tickets, then cancellation penalties and the full amount of the
              flights will be charged.
            </p>
            <p>
              A reservation can be changed only if space is available. An entire
              reservation that is changed will be considered a cancellation and
              will be subject to cancellation fees (100% loss of deposit).
            </p>
            <h3>Booking Changes</h3>
            <p>
              Once your booking in confirmed, the first change on your services
              is free. For subsequent changes a €50.00 fee will be charged.
            </p>
          </div>

          {/* Refund cards */}
          <div className="tw-mt-6 tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-5 lg:tw-gap-6">
            {refundCards.map((card) => (
              <div
                key={card.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6"
              >
                <h3 className="tw-text-[16px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-2">
                  {card.title}
                </h3>
                <p className="tw-m-0 tw-text-[13px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.body}
                </p>
              </div>
            ))}
          </div>

          <div className={`tw-mt-6 ${prose}`}>
            <p>
              Under any circumstances, there will be no refund for the promoted
              tours. The balance will be identified as &quot;Future Tour
              Credits&quot; to use in the future. Please contact{" "}
              <a
                href="mailto:help@travelshopbooking.com"
                target="_blank"
                rel="noopener noreferrer"
              >
                help@travelshopbooking.com
              </a>{" "}
              or your tour operator to change tour dates and other details.
            </p>
          </div>

          {/* Child pricing table */}
          <div className="tw-mt-6 tw-overflow-x-auto tw-rounded-2xl tw-border tw-border-solid tw-border-[#ebe7f0]">
            <table className="tw-w-full tw-border-collapse tw-text-left tw-text-[14px]">
              <thead>
                <tr className="tw-bg-[#faf9fc]">
                  {[
                    "",
                    "UNDER 2 YEARS OLD",
                    "2-6 Years OLD",
                    "7-11 YEARS OLD",
                    "ABOVE 11 YEARS OLD",
                  ].map((h, i) => (
                    <th
                      key={i}
                      className="tw-px-4 tw-py-3 tw-font-bold tw-text-[#14101c] tw-whitespace-nowrap"
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[
                  ["LAND TOURS", "Free", "Free", "25%", "Full amount"],
                  [
                    "TOURS WITH DOMESTIC FLIGHTS",
                    "Euro 20 for flight tickets",
                    "50%",
                    "25%",
                    "Full amount",
                  ],
                  ["BABY SEAT REQUEST FOR BUS*", "+25%", "+25%", "N/A", "N/A"],
                ].map((row) => (
                  <tr
                    key={row[0]}
                    className="tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0]"
                  >
                    {row.map((cell, j) => (
                      <td
                        key={j}
                        className={`tw-px-4 tw-py-3 ${j === 0 ? "tw-font-semibold tw-text-[#14101c]" : "tw-text-[#5d556c]"}`}
                      >
                        {cell}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className={`tw-mt-4 ${prose}`}>
            <p>
              *Baby seats for buses will have an extra charge of 25% of the tour
              cost and they must be requested prior to the starting date of the
              tour. Where the baby is carried by the parents, there will be no
              extra charge. **Children under 18 years old must be accompanied by
              an adult, without exception.
            </p>
          </div>

          {/* Info image cards */}
          <div className="tw-mt-10 tw-space-y-8 lg:tw-space-y-10">
            {infoCards.map((card) => (
              <div
                key={card.title}
                className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[360px_1fr] tw-gap-8 tw-items-center"
              >
                <img
                  src={card.image}
                  alt={card.title}
                  loading="lazy"
                  className={`tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10 ${
                    card.imageLeft ? "" : "lg:tw-order-2"
                  }`}
                />
                <div className={card.imageLeft ? "" : "lg:tw-order-1"}>
                  <h2 className="tw-text-[20px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                    {card.title}
                  </h2>
                  <div className="tw-mt-3 tw-space-y-3 tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c]">
                    {card.body.map((p, i) => (
                      <p key={i} className="tw-m-0">
                        {p}
                      </p>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Visa + closing prose */}
          <div className={`tw-mt-10 ${prose}`}>
            <p>
              TravelShop Booking will provide invitation letters to obtain any
              of these visas for those who have booked and paid a deposit. The
              cost of visas is not included in your tour package. Check your
              local embassy and the information below for visa procedures.
            </p>
            <p>
              For up to date Turkey visa information from the Turkish Ministry
              of Foreign Affairs follow this link:
              www.mfa.gov.tr/visa-information-for-foreigners.en.mfa
            </p>
            <p>
              Citizens of most countries can obtain a visa at the border. For up
              to date border information from the Turkish Ministry of Foreign
              Affairs follow this link:
              www.mfa.gov.tr/visa-fees-at-border-gates-for-2010.en.mfa
            </p>
            <p>
              At Istanbul Airport (IST) you can get your visa at the visa
              counter on your left just before the passport control area.
              Passport control will send you back to the visa section if you do
              not have a valid visa. It&quot;s a good idea to have the correct
              money in the correct currency for your visa.
            </p>
            <p>
              As of April 17, 2013, electronic visa (e-Visa) replaces
              &quot;sticker visa&quot; which was issued at the border crossings.
              Applicants just need to log on to the following link, provide the
              requested information, (after the application is approved) make
              online payment and download their e-Visa: www.evisa.gov.tr
            </p>
            <p>
              TravelShop Booking Murtis Tour reserves the right to decline,
              accept or retain any person as a tour passenger should such
              person&quot;s health, mental condition, physical infirmity or
              general attitude impede the operation of the tour or the rights,
              welfare or enjoyment of other tour passengers. Please let staff
              know if you have any health problems when you are making your
              booking.
            </p>
            <p>
              Passengers will be prohibited from travelling in the event of
              pregnancy in advance of 27 weeks or more in accordance with the
              terms of their own safety and their own health. Travel may be
              permitted in the instance where sufficient medical documentation
              is provided till 24- 26 weeks of the pregnancy.
            </p>
            <p>
              TravelShop Booking provides private services for handicapped
              people with prior request. Please contact our staff to make
              arrangements.
            </p>
            <p>
              Special dietary requirements of passengers are catered for in the
              menu including vegetarian, diabetic, children menus and
              dairy-free. For meal requests, please confirm with TravelShop
              Booking Murtis Tour at least 2 weeks before your tour start date.
              As you know, around the world you do not have to pay tips if you
              are not happy with the service, but especially in Turkey, tipping
              is a cultural fact. People who give you good service expect a tip.
            </p>
            <p>
              Our company will always give you quality service, but we do not
              include tips in our package prices. Normally, tour guide tips are
              2 Euro per person per day while driver tips are 1 euro per person
              per day. This will vary according to the quality of their service,
              so it will be up to customer to decide on the given amount.
              Remember this is not an obligatory service, but rather a part of
              the Turkish culture.
            </p>
            <p className="!tw-mb-0">
              <strong>
                For further information, please contact directly with your Tour
                Operator.
              </strong>
            </p>
          </div>
        </div>
      </section>
    </main>
  );
}
